('eliminate', '/ɪˈlɪmɪneɪt/', 'verb', 'To completely remove or get rid of something', '消除；淘汰；排除', 2, 800, '["cet4"]', '来自拉丁语eliminare，e-（出）+ limen（门槛），原意为逐出门外，即彻底排除', '[{"en": "The government aims to eliminate poverty.", "cn": "政府旨在消除贫困。"}, {"en": "Three teams were eliminated in the first round.", "cn": "三支队伍在第一轮被淘汰。"}]', '["remove", "eradicate"]', '["add", "include"]'),
('emotion', '/ɪˈmoʊʃn/', 'noun', 'A strong feeling such as love, fear, or anger', '情感；情绪；感动', 1, 600, '["cet4"]', '来自拉丁语emovere，e-（出）+ movere（移动），原意为内心被搅动产生的强烈感受', '[{"en": "She showed no emotion when she heard the news.", "cn": "她听到消息时没有表现出任何情绪。"}, {"en": "Music can evoke powerful emotions.", "cn": "音乐能唤起强烈的情感。"}]', '["feeling", "sentiment"]', '["apathy", "indifference"]'),
