('indicate', '/ˈɪndɪkeɪt/', 'verb', 'To point out or show something; to be a sign of', '表明；指出；暗示', 1, 500, '["cet4"]', '来自拉丁语indicare，in-（在…上）+ dicare（宣告），表示通过迹象指明或显示', '[{"en": "Research indicates that exercise improves mental health.", "cn": "研究表明锻炼能改善心理健康。"}, {"en": "The arrow on the sign indicates the direction.", "cn": "标志上的箭头指明了方向。"}]', '["show", "suggest"]', '["conceal", "hide"]'),
('individual', '/ˌɪndɪˈvɪdʒuəl/', 'noun', 'A single human being considered separately from a group', '个人；个体；独特的', 1, 400, '["cet4"]', '来自拉丁语individuus，in-（不）+ dividuus（可分的），表示不可再分的最小单位', '[{"en": "Each individual has the right to express their opinion.", "cn": "每个人都有表达自己观点的权利。"}, {"en": "The needs of the individual must be considered.", "cn": "必须考虑个人的需求。"}]', '["person", "entity"]', '["group", "collective"]'),
('influence', '/ˈɪnfluəns/', 'noun', 'The capacity to have an effect on someone''s behavior', '影响；影响力；势力', 1, 400, '["cet4"]', '来自拉丁语influere，in-（进入）+ fluere（流动），原指星体向人间倾注的神秘力量', '[{"en": "Parents have a great influence on their children.", "cn": "父母对孩子有很大的影响。"}, {"en": "He used his political influence to get the law changed.", "cn": "他利用自己的政治影响力推动了法律修改。"}]', '["effect", "impact"]', '["powerlessness", "insignificance"]'),
('maintain', '/meɪnˈteɪn/', 'verb', 'To cause something to continue; to keep in good condition', '维持；保养；坚持；赡养', 1, 400, '["cet4"]', '来自拉丁语manu tenere，manus意为手，tenere意为持有，原意为握在手中保持', '[{"en": "It is important to maintain good health.", "cn": "保持良好的健康很重要。"}, {"en": "The building is well maintained.", "cn": "这栋楼保养得很好。"}]', '["preserve", "sustain"]', '["neglect", "abandon"]'),
('negotiate', '/nɪˈɡoʊʃieɪt/', 'verb', 'To discuss something in order to reach an agreement', '谈判；协商；顺利通过', 1, 700, '["cet4"]', '来自拉丁语negotiari，nec-（不）+ otium（闲暇），原意为不空闲忙于事务', '[{"en": "The two sides are negotiating a peace agreement.", "cn": "双方正在谈判和平协议。"}, {"en": "She negotiated a better salary.", "cn": "她谈判获得了更高的薪水。"}]', '["bargain", "mediate"]', '["impose", "dictate"]'),
('jealousy', '/ˈdʒeləsi/', 'noun', 'The feeling of being envious of someone', '嫉妒；猜忌；羡慕', 2, 1200, '["cet4"]', '源自古法语jalousie，来自希腊语zelos（热情、竞争），表示对他人拥有的东西感到不满', '[{"en": "His success aroused the jealousy of his colleagues.", "cn": "他的成功引起了同事们的嫉妒。"}, {"en": "Jealousy can destroy relationships.", "cn": "嫉妒可以摧毁关系。"}]', '["envy", "resentment"]', '["admiration", "contentment"]'),
('judgment', '/ˈdʒʌdʒmənt/', 'noun', 'The ability to make considered decisions', '判断；审判；评价', 1, 700, '["cet4"]', '来自拉丁语judicium，judex意为法官，jus（法律）+ dicare（说），表示法官依据法律做出的判断', '[{"en": "She showed good judgment in choosing her career.", "cn": "她在选择职业方面表现出良好的判断力。"}, {"en": "The court delivered its judgment yesterday.", "cn": "法庭昨天做出了判决。"}]', '["decision", "verdict"]', '["indecision", "uncertainty"]'),
('justify', '/ˈdʒʌstɪfaɪ/', 'verb', 'To show or prove to be right or reasonable', '证明…正当；为…辩护', 2, 900, '["cet4"]', '由just（公正的，来自拉丁语justus）和-fy（使成为）组合，表示使某事显得正当合理', '[{"en": "How can you justify such a large expense?", "cn": "你怎么证明如此大的开支是合理的？"}, {"en": "The end does not justify the means.", "cn": "目的不能证明手段正当。"}]', '["defend", "vindicate"]', '["condemn", "criticize"]'),
('labor', '/ˈleɪbər/', 'noun', 'Work, especially hard physical work', '劳动；劳工；劳工运动', 1, 500, '["cet4"]', '来自拉丁语labor（劳动、辛苦），原指身体的劳累和辛苦工作', '[{"en": "Manual labor is essential in construction.", "cn": "体力劳动在建筑业中是必不可少的。"}, {"en": "The cost of labor has increased significantly.", "cn": "劳动力成本大幅上升。"}]', '["work", "toil"]', '["leisure", "rest"]'),
('launch', '/lɔːntʃ/', 'verb', 'To start a new activity; to send a rocket into space', '发射；发起；推出；启动', 1, 600, '["cet4"]', '源自古法语lanchier，来自拉丁语lanceare（投掷长矛），lancea意为长矛', '[{"en": "The company launched a new product last month.", "cn": "公司上个月推出了一款新产品。"}, {"en": "The rocket was launched successfully.", "cn": "火箭发射成功。"}]', '["initiate", "start"]', '["terminate", "conclude"]'),
('landscape', '/ˈlændskeɪp/', 'noun', 'All the visible features of an area of land', '风景；景观；全景', 1, 800, '["cet4"]', '由land（土地）和scape（景象，源自荷兰语-schap）组合，原为绘画术语', '[{"en": "The landscape of the countryside is beautiful.", "cn": "乡村的风景很美。"}, {"en": "The political landscape has changed dramatically.", "cn": "政治格局发生了巨大变化。"}]', '["scenery", "vista"]', '["indoors", "interior"]'),
('likewise', '/ˈlaɪkwaɪz/', 'adverb', 'In the same way; also; similarly', '同样地；也；类似地', 2, 1200, '["cet4"]', '由like（相似的）和-wise（方式）组合，表示以同样的方式', '[{"en": "Watch what I do and do likewise.", "cn": "看着我怎么做，然后照做。"}, {"en": "She was awarded a prize, and her partner likewise.", "cn": "她获得了奖品，她的搭档也获得了。"}]', '["similarly", "also"]', '["differently", "otherwise"]'),
('manufacture', '/ˌmænjuˈfæktʃər/', 'verb', 'To make goods on a large scale using machinery', '制造；生产；捏造', 1, 700, '["cet4"]', '来自拉丁语manufactura，manus意为手，factura意为制作，原指手工制作', '[{"en": "The factory manufactures electronic components.", "cn": "这家工厂生产电子元件。"}, {"en": "The company manufactures cars in three countries.", "cn": "该公司在三个国家制造汽车。"}]', '["produce", "fabricate"]', '["destroy", "demolish"]'),
('obligation', '/ˌɑːblɪˈɡeɪʃn/', 'noun', 'A duty or commitment; a legal or moral requirement', '义务；责任；债务', 2, 1000, '["cet4"]', '来自拉丁语obligatio，ob-（向）+ ligare（绑），原意为被绑定的义务', '[{"en": "Parents have an obligation to educate their children.", "cn": "父母有教育孩子的义务。"}, {"en": "You are under no obligation to accept the offer.", "cn": "你没有义务接受这个提议。"}]', '["duty", "responsibility"]', '["freedom", "exemption"]'),
('oppose', '/əˈpoʊz/', 'verb', 'To actively resist or refuse to comply with', '反对；对抗；抵制', 1, 600, '["cet4"]', '来自拉丁语opponere，ob-（对面）+ ponere（放置），表示放置在对面以示反对', '[{"en": "Many people oppose the new policy.", "cn": "许多人反对新政策。"}, {"en": "She opposed the plan to build a new highway.", "cn": "她反对修建新高速公路的计划。"}]', '["resist", "object to"]', '["support", "endorse"]'),
('origin', '/ˈɔːrɪdʒɪn/', 'noun', 'The point or place where something begins', '起源；来源；出身', 1, 600, '["cet4"]', '来自拉丁语origo，oriri意为升起、出现，表示事物的起点或来源', '[{"en": "The origin of the universe is still a mystery.", "cn": "宇宙的起源仍然是一个谜。"}, {"en": "She is of Chinese origin.", "cn": "她具有中国血统。"}]', '["source", "beginning"]', '["end", "conclusion"]'),
('participate', '/pɑːrˈtɪsɪpeɪt/', 'verb', 'To take part in an activity or event', '参与；参加；分享', 1, 500, '["cet4"]', '来自拉丁语participare，pars意为部分，capere意为拿取，表示拿取自己的一份即参与', '[{"en": "All students are encouraged to participate in class discussions.", "cn": "鼓励所有学生参与课堂讨论。"}, {"en": "She participated in the marathon last year.", "cn": "她去年参加了马拉松比赛。"}]', '["join", "engage"]', '["withdraw", "abstain"]'),
